279: /**
280:  * Clears the current user session from the session store, setting the session
281:  * to an unauthenticated state. This is typically called during logout to reset
282:  * the application's authentication state.
283:  *
284:  * @example
285:  * ```ts
286:  * import { clearCurrentUser } from '@openmrs/esm-api';
287:  * // During logout
288:  * clearCurrentUser();
289:  * ```
290:  */
291: export function clearCurrentUser() {
292:   sessionStore.setState(
293:     {
294:       loaded: true,
295:       session: { authenticated: false, sessionId: '' },
296:     },
297:     true,
298:   );
299: }
