301: /**
302:  * Checks whether the given user has access based on the required privilege(s).
303:  * A user has access if they have the required privilege(s) or if they are a
304:  * "System Developer" (super user). If no privilege is required, access is granted.
305:  *
306:  * @param requiredPrivilege A single privilege string or an array of privilege strings
307:  *   that the user must have. If an array is provided, the user must have ALL privileges.
308:  * @param user The user object containing their privileges and roles.
309:  * @returns `true` if the user has access, `false` otherwise. Returns `true` if no
310:  *   privilege is required, and `false` if the user is undefined but a privilege is required.
311:  *
312:  * @example
313:  * ```ts
314:  * import { userHasAccess } from '@openmrs/esm-api';
315:  * const hasAccess = userHasAccess('View Patients', currentUser);
316:  * const hasMultipleAccess = userHasAccess(['View Patients', 'Edit Patients'], currentUser);
317:  * ```
318:  */
319: export function userHasAccess(
320:   requiredPrivilege: string | Array<string>,
321:   user: { privileges: Array<Privilege>; roles: Array<Role> },
322: ) {
323:   if (user === undefined) {
324:     // if the user hasn't been loaded, then return false iff there is a required privilege
325:     return !Boolean(requiredPrivilege);
326:   }
327: 
328:   if (!Boolean(requiredPrivilege)) {
329:     // if user exists but no requiredPrivilege is defined
330:     return true;
331:   }
332: 
333:   return userHasPrivilege(requiredPrivilege, user) || isSuperUser(user);
334: }
