351: export function getLoggedInUser() {
352:   let user: LoggedInUser;
353:   let unsubscribe: () => void;
354:   return new Promise<LoggedInUser>((res) => {
355:     const handler = (state: SessionStore) => {
356:       if (state.loaded && state.session.user) {
357:         user = state.session.user;
358:         res(state.session.user);
359: 
360:         if (unsubscribe) {
361:           unsubscribe();
362:         }
363:       }
364:     };
365:     handler(sessionStore.getState());
366:     if (!user) {
367:       unsubscribe = sessionStore.subscribe(handler);
368:     }
369:   });
370: }
